<?php
namespace Copot\Core;
final class MediaUsageRepository{public function __construct(private Database $database){}private function t():string{return $this->database->table('media_usages');}public function forMedia(MediaId|int $id,bool $lock=false):array{$id=$id instanceof MediaId?$id:new MediaId($id);$s=$this->database->connection()->prepare('SELECT * FROM '.$this->t().' WHERE media_id=:id ORDER BY consumer_type,consumer_id,usage_key'.($lock?' FOR UPDATE':''));$s->execute(['id'=>$id->value()]);return array_map(fn(array $r):MediaUsage=>new MediaUsage(new MediaId((int)$r['media_id']),(string)$r['consumer_type'],(int)$r['consumer_id'],(string)$r['usage_key'],(string)$r['created_at']),$s->fetchAll());}public function register(MediaId|int $id,string $type,int $consumer,string $key):void{$id=$id instanceof MediaId?$id:new MediaId($id);$s=$this->database->connection()->prepare('INSERT IGNORE INTO '.$this->t().' (media_id,consumer_type,consumer_id,usage_key,created_at) VALUES (:id,:type,:consumer,:key,NOW())');$s->execute(['id'=>$id->value(),'type'=>trim($type),'consumer'=>$consumer,'key'=>trim($key)]);}public function remove(MediaId|int $id,string $type,int $consumer,string $key):void{$id=$id instanceof MediaId?$id:new MediaId($id);$s=$this->database->connection()->prepare('DELETE FROM '.$this->t().' WHERE media_id=:id AND consumer_type=:type AND consumer_id=:consumer AND usage_key=:key');$s->execute(['id'=>$id->value(),'type'=>trim($type),'consumer'=>$consumer,'key'=>trim($key)]);}public function forConsumer(string $type,int $consumer,string $key=''):array{$sql='SELECT * FROM '.$this->t().' WHERE consumer_type=:type AND consumer_id=:consumer';$p=['type'=>trim($type),'consumer'=>$consumer];if($key!==''){$sql.=' AND usage_key=:key';$p['key']=trim($key);}$s=$this->database->connection()->prepare($sql);$s->execute($p);return array_map(fn(array $r):MediaUsage=>new MediaUsage(new MediaId((int)$r['media_id']),(string)$r['consumer_type'],(int)$r['consumer_id'],(string)$r['usage_key'],(string)$r['created_at']),$s->fetchAll());}}
